package io.github.hellsong.composemonitor.helper

import androidx.compose.runtime.Composable
import androidx.compose.runtime.NonSkippableComposable
import androidx.compose.runtime.State
import androidx.compose.runtime.snapshots.Snapshot

/**
 * Marks the functions that code generated by the composemonitor compiler plugin calls.
 * Their names and signatures are matched by `MonitorSymbols` in the compiler plugin; keep them in sync.
 */
@RequiresOptIn(message = "Called by code that the composemonitor compiler plugin generates.")
@Retention(AnnotationRetention.BINARY)
@Target(AnnotationTarget.FUNCTION)
annotation class InternalComposeMonitorApi

@InternalComposeMonitorApi
fun monitorNewList(): MutableList<Pair<String, Any?>> = ArrayList()

@InternalComposeMonitorApi
fun monitorAdd(nameValueList: MutableList<Pair<String, Any?>>, name: String, value: Any?) {
    nameValueList.add(name to value)
}

/**
 * Unwraps `State` values and hands the parameters and states of a `@ComposableMonitor` function to [ComposeMonitorInspector].
 */
@InternalComposeMonitorApi
@Composable
@NonSkippableComposable
fun CollectAndPrintValues(composableName: String, nameValueList: List<Pair<String, Any?>>) {
    ComposeMonitorInspector(trackMap = nameValueList.toTrackMap(), composableName = composableName)
}

internal fun List<Pair<String, Any?>>.toTrackMap(): Map<String, Any?> = mutableMapOf<String, Any?>().apply {
    this@toTrackMap.forEach {
        var value: Any? = it.second
        var name = it.first
        if (value is State<*>) {
            // Reading without observation keeps CollectAndPrintValues from subscribing to the state itself, which
            // would recompose it on its own and log a change the monitored function never saw.
            value = Snapshot.withoutReadObservation { value.value }
            val end = "\$delegate"
            if (name.endsWith(end)) {
                name = name.substring(0, name.length - end.length)
            }
        }
        put(name, value)
    }
}
